-- Official-source verified expansion: customer service and CRM agents.

insert into public.tools (
 name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,
 korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,
 is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at
)
select * from (values
('Tidio Lyro','지원 문서를 학습해 고객 질문에 답하고 업무를 처리·인계하는 AI 상담원 #고객지원 #AI챗봇 #헬프데스크 #이커머스','Tidio Lyro는 FAQ·웹사이트·Zendesk 문서를 바탕으로 고객 질문에 답하고 예약·주문 같은 작업을 수행하며, 답할 수 없는 요청을 사람 상담원이나 기존 헬프데스크로 넘기는 AI 고객지원 에이전트입니다.','https://www.tidio.com/ai-agent/','https://www.tidio.com/favicon.ico','Freemium','$0','최초 50대화 무료 · 유료 대화당 $0.50부터',array['모든 신규 프로젝트에 갱신되지 않는 Lyro 대화 50건을 무료 제공합니다.','유료 Lyro 대화는 건당 $0.50부터이며 월 50~1,000건 할당량을 선택합니다.','기존 Zendesk·Salesforce 등에 연결하는 Lyro Connect는 상위 플랜과 영업 상담이 필요합니다.'],'USD','https://www.tidio.com/pricing/',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격·도움말을 확인했습니다. 실제 상담, 한국어 품질과 외부 시스템 작업은 직접 테스트하지 않았습니다.',false,true,'https://developers.tidio.com/','Native','specialized',array['AI 고객 질의 해결','지원 지식 학습','업무 실행·상담원 인계'],array['Zendesk·Salesforce 연결','성과 분석','OpenAPI'],array['최초 50대화 무료 검증','한 대화 내 여러 답변을 한 건으로 계산','기존 헬프데스크 연결'],array['반복 문의를 자동화하는 고객지원팀','상담과 판매를 함께 운영하는 이커머스'],array['무료 50대화는 일회성이며 갱신되지 않습니다.','15분 비활성 후 새 대화로 다시 과금될 수 있습니다.','정책·환불·개인정보 답변은 사람 검토와 인계 규칙이 필요합니다.'],array['https://www.tidio.com/ai-agent/','https://help.tidio.com/hc/en-us/articles/13924459295900-The-Lyro-AI-agent-limit'],now(),now()),
('Gorgias AI Agent','쇼핑몰 문의를 해결하고 상품 추천·주문 작업을 수행하는 이커머스 AI #고객지원 #이커머스 #헬프데스크 #AI에이전트','Gorgias AI Agent는 Shopify 등 쇼핑몰 데이터와 정책을 이용해 고객 문의에 답하고 주문 변경·환불 같은 지원 작업과 상품 추천을 수행하며 모든 채널을 하나의 헬프데스크로 연결합니다.','https://www.gorgias.com/ai-agent','https://www.gorgias.com/favicon.ico','Paid',null,'무료 체험 · 헬프데스크 사용량+AI 해결 건 과금',array['AI Agent는 모든 유료 헬프데스크 플랜에서 사용할 수 있습니다.','헬프데스크는 월 티켓 구간에 따라 과금되고 좌석 수 기준은 아닙니다.','AI Agent는 대화에 답한 횟수가 아니라 실제 해결한 대화에 대해 과금됩니다.'],'USD','https://www.gorgias.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격·개발자 페이지를 확인했습니다. 정확한 결제액, 해결 판정과 API는 직접 테스트하지 않았습니다.',false,true,'https://developers.gorgias.com/','Native','specialized',array['이커머스 AI 상담','주문·환불 작업','상품 추천'],array['통합 헬프데스크','음성·SMS 부가 기능','개발자 API'],array['Shopify 중심의 깊은 상거래 연결','좌석이 아닌 티켓량 기준 헬프데스크','해결된 대화 중심 AI 과금'],array['Shopify 고객지원을 운영하는 브랜드','지원과 판매 전환을 함께 관리하는 팀'],array['공개 페이지에서 정확한 구간별 금액이 동적으로 표시될 수 있습니다.','Voice·SMS는 별도 사용량 비용이 발생합니다.','자동 환불·주문 변경은 권한과 승인 정책이 필요합니다.'],array['https://www.gorgias.com/pricing','https://developers.gorgias.com/'],now(),now()),
('Ada','메시지·이메일·음성 채널에서 복잡한 고객지원 절차를 수행하는 기업 AI #고객지원 #콜센터 #AI에이전트 #업무자동화','Ada는 기업 지원 지식과 시스템을 연결해 메시지·이메일·음성 고객 요청을 처리하고, Playbook으로 복잡한 표준 절차를 자동화하며 성능 측정·테스트·코칭을 제공하는 고객경험 AI 플랫폼입니다.','https://www.ada.cx/','https://www.ada.cx/favicon.ico','Paid',null,'기업 맞춤 견적',array['공개 셀프서비스 가격 없이 상담과 맞춤 데모를 통해 견적을 제공합니다.','계약은 지원 채널·대화량·통합·기업 보안 요구에 따라 달라질 수 있습니다.','도입 전 기존 채널과 자동화 가능 업무를 검토하는 상담을 제공합니다.'],'USD','https://www.ada.cx/demo/',now(),'None',true,true,false,false,false,'official_sources','공식 제품·데모·문서를 확인했습니다. 가격, 실제 해결률과 시스템 통합은 직접 테스트하지 않았습니다.',false,true,'https://docs.ada.cx/','Native','specialized',array['다채널 고객지원 AI','업무 Playbook','에이전트 테스트·코칭'],array['음성·이메일·메시징','기업 시스템 통합','성과 측정'],array['복잡한 지원 절차 자동화','모든 주요 지원 채널 통합','기업용 테스트·안전 기능'],array['대규모 고객센터를 운영하는 기업','메시지와 음성 지원을 통합하려는 조직'],array['셀프서비스 가격이 없어 견적 비교가 어렵습니다.','초기 지식·통합·업무 절차 설계가 필요합니다.','규제 업무는 가드레일과 사람 인계를 구성해야 합니다.'],array['https://www.ada.cx/demo/','https://docs.ada.cx/'],now(),now()),
('Sierra','기업 시스템과 연결해 고객 요청을 해결하고 실제 작업을 수행하는 AI 에이전트 #고객지원 #AI에이전트 #콜센터 #SDK','Sierra Agent OS는 고객 지식과 내부 시스템을 연결해 구독 변경·보증 접수 같은 다단계 요청을 처리하고 채팅·전화·이메일·SMS에 배포하며 시뮬레이션과 디버깅으로 동작을 검증합니다.','https://sierra.ai/','https://sierra.ai/favicon.ico','Paid',null,'기업 맞춤 견적',array['공개 정액 요금 대신 기업 도입 상담을 통해 견적을 제공합니다.','가격은 채널·사용량·통합·지원과 계약 범위에 따라 달라질 수 있습니다.','Agent Studio와 개발자용 Agent SDK를 함께 제공합니다.'],'USD','https://sierra.ai/',now(),'None',true,true,false,false,false,'official_sources','공식 Agent SDK·제품·신뢰 자료를 확인했습니다. 가격, 시뮬레이션과 실제 작업 수행은 직접 테스트하지 않았습니다.',false,true,'https://sierra.ai/product/agent-sdk','Native','specialized',array['고객지원 AI 에이전트','다단계 업무 실행','옴니채널 배포'],array['Agent Studio·SDK','시뮬레이션·디버깅','상담원 인계'],array['코드와 노코드 제작 방식 제공','실제 고객 업무 수행','배포 전 시뮬레이션과 행동 추적'],array['복잡한 고객 여정을 자동화하는 기업','개발팀과 CX팀이 함께 에이전트를 운영하는 조직'],array['공개 가격 없이 기업 계약이 필요합니다.','내부 시스템 연결과 안전한 작업 권한 설계가 필요합니다.','고객 데이터와 규제 요건에 맞춘 운영 검증이 필요합니다.'],array['https://sierra.ai/product/agent-sdk','https://sierra.ai/'],now(),now()),
('Salesforce Agentforce','CRM 데이터와 Flow를 이용해 고객·직원 업무를 수행하는 Salesforce AI #CRM #AI에이전트 #고객지원 #세일즈','Salesforce Agentforce는 Agent Builder와 CRM·Data 360·Flow를 바탕으로 고객지원, 영업과 직원용 에이전트를 만들고 질문 응답부터 레코드 갱신·업무 실행·음성 지원까지 연결합니다.','https://www.salesforce.com/agentforce/','https://www.salesforce.com/favicon.ico','Freemium','$0','Foundations 무료 · Action당 $0.10 또는 대화당 $2',array['Salesforce Foundations는 Agentforce Builder 등 시작 기능을 무료 제공합니다.','Flex Credits는 10만 크레딧당 $500이며 일반 Action 하나는 20크레딧, 즉 $0.10입니다.','외부 고객 에이전트는 선구매 방식으로 대화당 $2 옵션도 제공합니다.'],'USD','https://www.salesforce.com/agentforce/pricing/',now(),'Full Support',true,true,false,false,false,'official_sources','Salesforce 공식 제품·가격·도움말을 확인했습니다. 에이전트 구축, 한국어와 실제 Action 사용량은 직접 테스트하지 않았습니다.',false,true,'https://developer.salesforce.com/docs/platform/einstein-genai/overview','Augmented','general',array['CRM AI 에이전트','레코드·Flow 작업','고객·직원 지원'],array['Agent Builder','Agentforce Voice','Digital Wallet'],array['Salesforce 데이터와 권한 체계 활용','무료 Builder 시작점','Action·대화·사용자형 과금 선택'],array['Salesforce를 사용하는 영업·지원 조직','CRM 업무를 에이전트로 자동화하는 기업'],array['Salesforce 기본 라이선스와 구현 비용이 별도로 발생할 수 있습니다.','Flex Credit과 대화형 요금은 같은 조직에서 함께 쓰지 못합니다.','업무 설계에 따라 Action 수와 실제 비용이 크게 달라집니다.'],array['https://www.salesforce.com/agentforce/pricing/','https://help.salesforce.com/s/articleView?id=004811240&type=1'],now(),now())
) as seed(name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at)
where not exists(select 1 from public.tools where lower(tools.url)=lower(seed.url));

with assignments(tool_url,category_slug) as (values
('https://www.tidio.com/ai-agent/','business-marketing'),('https://www.tidio.com/ai-agent/','productivity'),
('https://www.gorgias.com/ai-agent','business-marketing'),('https://www.gorgias.com/ai-agent','productivity'),
('https://www.ada.cx/','business-marketing'),('https://www.ada.cx/','productivity'),
('https://sierra.ai/','business-marketing'),('https://sierra.ai/','productivity'),
('https://www.salesforce.com/agentforce/','business-marketing'),('https://www.salesforce.com/agentforce/','productivity')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict(tool_id,category_id) do nothing;
